const t = $('Called by Router (audit)').first().json;
const dd = function (a) { const seen = {}; const out = []; for (let i = 0; i < a.length; i++) { const k = JSON.stringify(a[i]); if (!seen[k]) { seen[k] = 1; out.push(a[i]); } } return out; };
const ctl = dd($('Read control').all().map(function (i) { return i.json; }));
const adminRow = ctl.find(function (r) { return r.Setting === 'Admin Slack IDs'; });
const admins = String(adminRow ? adminRow.Value : '').split(/[,\s]+/).filter(function (x) { return x; });
const base = { channel: t.channel, thread_ts: t.thread_ts, user: t.user };
if (admins.indexOf(String(t.user)) < 0) {
  return [{ json: Object.assign({}, base, { reply_text: ':lock: Audit replay is limited to admins.', log_action: 'Audit replay denied', log_target: 'user ' + t.user, log_result: 'Not an admin' }) }];
}
const clean = function (v, n) { return String(v == null ? '' : v).replace(/<[!#@]/g, '< ').replace(/[\r\n]+/g, ' ').slice(0, n); };
const audit = dd($('Read audit log').all().map(function (i) { return i.json; })).filter(function (r) { return r.Action; });
const refunds = dd($('Read refunds').all().map(function (i) { return i.json; })).filter(function (r) { return r['Order ID']; });
const line = function (r) { return '`' + clean(r.Time, 19) + '` *' + clean(r.Workflow, 40) + '*: ' + clean(r.Action, 80) + (r.Target ? ' (' + clean(r.Target, 70) + ')' : '') + ' | approved by: ' + clean(r['Approved by'] || 'n/a', 40) + (r.Result ? ' | ' + clean(r.Result, 100) : ''); };
const text = String(t.text || '');
const m = text.match(/ORD[-\s]?(\d{4})/i);
let head = '';
let rows = [];
let extra = '';
if (m) {
  const id = 'ORD-' + m[1];
  rows = audit.filter(function (r) { return String(r.Target || '').indexOf(id) >= 0; });
  head = ':mag: *Replay for ' + id + '* (' + rows.length + ' logged action' + (rows.length === 1 ? '' : 's') + ')';
  const rf = refunds.filter(function (r) { return r['Order ID'] === id; });
  const limRow = ctl.find(function (r) { return r.Setting === 'Auto refund limit (USD)'; });
  const capRow = ctl.find(function (r) { return r.Setting === 'Daily auto refund cap (USD)'; });
  for (let k = 0; k < rf.length; k++) {
    const r = rf[k];
    const auto = String(r['Decided by'] || '').indexOf('policy') === 0;
    extra += '\n*Refund record:* $' + clean(r['Amount USD'], 10) + ' ' + clean(r.Decision, 20) + ' by ' + clean(r['Decided by'], 40) + ' at ' + clean(r.Time, 19) + (r.Reason ? ', reason given: ' + clean(r.Reason, 80) : '');
    extra += auto ? '\n*Why:* auto-approved by policy. The amount was at or under the auto limit (currently $' + clean(limRow ? limRow.Value : '?', 10) + ') and within the daily cap (currently $' + clean(capRow ? capRow.Value : '?', 10) + '). Limits shown are the current values, not necessarily those at the time.' : '\n*Why:* the amount was over the automatic limit or cap, so a human decided.';
  }
} else {
  const nm = text.match(/(?:last|recent|latest)\s+(\d{1,2})/i);
  const n = nm ? Math.min(10, Math.max(1, Number(nm[1]))) : 5;
  rows = audit.slice(-n);
  head = ':mag: *Last ' + rows.length + ' logged actions*';
}
let body = rows.length ? rows.map(line).join('\n') : '_Nothing logged for that._';
const note = '\n_Built only from the Audit Log and Refunds sheet. Original message text is not stored._';
let reply = head + '\n' + body + extra + note;
if (reply.length > 3500) { reply = reply.slice(0, 3400) + '\n... (truncated)' + note; }
return [{ json: Object.assign({}, base, { reply_text: reply, log_action: 'Audit replay viewed', log_target: m ? 'ORD-' + m[1] : 'recent actions', log_result: rows.length + ' rows shown to ' + t.user }) }];
